boolean poprawneNawiasy(String s) {
    Deque<Character> stos = new ArrayDeque<>();
    Map<Character, Character> pary = Map.of(')', '(', ']', '[', '}', '{');
    for (char znak : s.toCharArray()) {
        if (pary.containsValue(znak)) { // znak otwierajacy
            stos.push(znak);
        } else if (pary.containsKey(znak)) { // znak zamykajacy
            if (stos.isEmpty() || stos.pop() != pary.get(znak)) return false;
        }
    }
    return stos.isEmpty(); // wszystko domkniete, nic nie zostalo
}

int[] nastepnyWiekszy(int[] tab) {
    int[] wynik = new int[tab.length];
    Arrays.fill(wynik, -1);
    Deque<Integer> stos = new ArrayDeque<>(); // przechowuje INDEKSY, wartosci na stosie maleja od dolu do gory
    for (int i = 0; i < tab.length; i++) {
        while (!stos.isEmpty() && tab[stos.peek()] < tab[i]) {
            wynik[stos.pop()] = tab[i]; // znaleziono 'nastepny wiekszy' dla elementu ze szczytu
        }
        stos.push(i);
    }
    return wynik; // elementy pozostale na stosie na koniec nie maja nastepnika wiekszego - zostaja -1
}

boolean poprawneNawiasy_BLAD(String s) {
    Deque<Character> stos = new ArrayDeque<>();
    for (char znak : s.toCharArray()) {
        if (znak == '(') stos.push(znak);
        else if (znak == ')') {
            if (stos.pop() != '(') return false; // BLAD: brak sprawdzenia isEmpty() - wyjatek przy pustym stosie!
        }
    }
    return stos.isEmpty();
}

boolean poprawneNawiasy_OK(String s) {
    Deque<Character> stos = new ArrayDeque<>();
    for (char znak : s.toCharArray()) {
